这是您需要的待办清单页面HTML代码。它包含了完整的增删改查功能，并且利用浏览器本地存储，让您下次打开页面时任务依然存在。
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>待办清单 · 本地存储</title>
    <style>
        /* 全局样式，无外链，纯本地 */
        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;
            background: #f5f7fb;
            min-height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 1.5rem;
        }

        .todo-card {
            background: #ffffff;
            max-width: 600px;
            width: 100%;
            border-radius: 28px;
            box-shadow: 0 20px 40px -12px rgba(0, 0, 0, 0.15), 0 8px 24px -6px rgba(0, 0, 0, 0.05);
            padding: 2rem 1.8rem 2rem 1.8rem;
            transition: all 0.2s ease;
        }

        h1 {
            font-size: 2rem;
            font-weight: 600;
            letter-spacing: -0.02em;
            color: #1e293b;
            display: flex;
            align-items: center;
            gap: 0.5rem;
            margin-bottom: 0.25rem;
        }

        .subhead {
            font-size: 0.9rem;
            color: #64748b;
            margin-bottom: 1.8rem;
            border-left: 3px solid #94a3b8;
            padding-left: 0.75rem;
        }

        /* 新增任务区域 */
        .add-todo {
            display: flex;
            gap: 0.6rem;
            margin-bottom: 2rem;
        }

        .add-todo input {
            flex: 1;
            padding: 0.9rem 1.2rem;
            border: 1.5px solid #e2e8f0;
            border-radius: 60px;
            font-size: 1rem;
            background: #f8fafc;
            transition: border 0.2s, box-shadow 0.2s;
            outline: none;
            color: #0f172a;
        }

        .add-todo input:focus {
            border-color: #3b82f6;
            box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.15);
            background: #ffffff;
        }

        .add-todo input::placeholder {
            color: #94a3b8;
            font-weight: 400;
        }

        .add-todo button {
            background: #3b82f6;
            border: none;
            color: white;
            font-weight: 500;
            font-size: 1rem;
            padding: 0 1.8rem;
            border-radius: 60px;
            cursor: pointer;
            transition: background 0.2s, transform 0.1s;
            display: flex;
            align-items: center;
            justify-content: center;
            white-space: nowrap;
            box-shadow: 0 4px 10px rgba(59, 130, 246, 0.3);
        }

        .add-todo button:hover {
            background: #2563eb;
        }

        .add-todo button:active {
            transform: scale(0.97);
        }

        /* 任务列表 */
        .todo-list {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: 0.6rem;
            margin-bottom: 1.5rem;
            max-height: 400px;
            overflow-y: auto;
            padding-right: 4px;
        }

        .todo-list::-webkit-scrollbar {
            width: 6px;
        }

        .todo-list::-webkit-scrollbar-track {
            background: #f1f5f9;
            border-radius: 10px;
        }

        .todo-list::-webkit-scrollbar-thumb {
            background: #cbd5e1;
            border-radius: 10px;
        }

        .todo-item {
            display: flex;
            align-items: center;
            gap: 0.75rem;
            background: #ffffff;
            border: 1px solid #eef2f6;
            border-radius: 60px;
            padding: 0.5rem 0.5rem 0.5rem 1.2rem;
            transition: background 0.2s, border 0.2s, box-shadow 0.2s;
            box-shadow: 0 2px 6px rgba(0, 0, 0, 0.02);
        }

        .todo-item:hover {
            border-color: #d9e2ef;
            background: #fafdff;
        }

        /* 自定义复选框 */
        .todo-check {
            appearance: none;
            -webkit-appearance: none;
            width: 1.5rem;
            height: 1.5rem;
            border: 2px solid #cbd5e1;
            border-radius: 50%;
            background: #ffffff;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.15s ease;
            flex-shrink: 0;
            position: relative;
        }

        .todo-check:checked {
            background: #3b82f6;
            border-color: #3b82f6;
        }

        .todo-check:checked::after {
            content: "✓";
            color: white;
            font-size: 0.9rem;
            font-weight: bold;
            line-height: 1;
            display: block;
            transform: translateY(-1px);
        }

        .todo-check:focus-visible {
            outline: 2px solid #3b82f6;
            outline-offset: 2px;
        }

        /* 任务文本 */
        .todo-text {
            flex: 1;
            font-size: 1rem;
            color: #1e293b;
            word-break: break-word;
            padding: 0.4rem 0;
            transition: color 0.2s, text-decoration 0.2s;
            cursor: pointer;
            user-select: none;
        }

        .todo-item.completed .todo-text {
            text-decoration: line-through;
            color: #94a3b8;
        }

        /* 删除按钮 */
        .delete-btn {
            background: transparent;
            border: none;
            width: 2.2rem;
            height: 2.2rem;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.2rem;
            color: #94a3b8;
            cursor: pointer;
            transition: background 0.15s, color 0.15s;
            flex-shrink: 0;
            line-height: 1;
            padding: 0;
        }

        .delete-btn:hover {
            background: #fee2e2;
            color: #dc2626;
        }

        .delete-btn:active {
            background: #fecaca;
        }

        /* 空状态 */
        .empty-message {
            text-align: center;
            color: #94a3b8;
            font-size: 0.95rem;
            padding: 2rem 1rem;
            background: #f8fafc;
            border-radius: 60px;
            border: 1px dashed #d1d9e6;
            margin-bottom: 0.5rem;
        }

        /* 底部统计 */
        .footer-stats {
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 0.85rem;
            color: #64748b;
            padding-top: 0.5rem;
            border-top: 1px solid #eef2f6;
            margin-top: 0.5rem;
        }

        .clear-btn {
            background: none;
            border: none;
            color: #94a3b8;
            font-size: 0.85rem;
            cursor: pointer;
            padding: 0.4rem 0.8rem;
            border-radius: 40px;
            transition: background 0.15s, color 0.15s;
        }

        .clear-btn:hover {
            background: #f1f5f9;
            color: #475569;
        }

        .clear-btn:active {
            background: #e2e8f0;
        }

        /* 小响应调整 */
        @media (max-width: 480px) {
            .todo-card {
                padding: 1.5rem 1.2rem;
            }
            .add-todo button {
                padding: 0 1.2rem;
                font-size: 0.9rem;
            }
            .add-todo input {
                padding: 0.8rem 1rem;
            }
            h1 {
                font-size: 1.7rem;
            }
        }
    </style>
</head>
<body>
    <div class="todo-card">
        <h1>📋 待办清单</h1>
        <div class="subhead">所有任务保存在浏览器中，下次打开依然可见</div>

        <!-- 新增任务 -->
        <div class="add-todo">
            <input type="text" id="todoInput" placeholder="写一个任务..." autocomplete="off" maxlength="200">
            <button id="addBtn">添加</button>
        </div>

        <!-- 任务列表容器 -->
        <ul class="todo-list" id="todoList">
            <!-- 动态渲染 -->
        </ul>

        <!-- 底部统计与清除 -->
        <div class="footer-stats">
            <span id="taskCounter">0 个任务</span>
            <button class="clear-btn" id="clearCompletedBtn">清除已完成</button>
        </div>
    </div>

    <script>
        (function() {
            // ---------- 数据层 ----------
            const STORAGE_KEY = 'todo_list_app_v1';

            // 读取本地存储，返回任务数组
            function loadTodos() {
                try {
                    const stored = localStorage.getItem(STORAGE_KEY);
                    if (stored) {
                        const parsed = JSON.parse(stored);
                        // 确保是数组且每个元素有基本结构
                        if (Array.isArray(parsed)) {
                            return parsed.filter(item => item && typeof item === 'object' && 'id' in item && 'text' in item && 'completed' in item)
                                         .map(item => ({
                                             id: String(item.id),
                                             text: String(item.text).slice(0, 200), // 限制长度
                                             completed: Boolean(item.completed)
                                         }));
                        }
                    }
                } catch (e) {
                    console.warn('读取本地存储失败，使用空列表', e);
                }
                return []; // 默认空数组
            }

            // 保存任务到本地存储
            function saveTodos(todos) {
                try {
                    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
                } catch (e) {
                    console.warn('保存到本地存储失败', e);
                }
            }

            // ---------- 状态 ----------
            let todos = loadTodos(); // 当前任务数组

            // ---------- DOM 元素 ----------
            const todoInput = document.getElementById('todoInput');
            const addBtn = document.getElementById('addBtn');
            const todoListEl = document.getElementById('todoList');
            const taskCounter = document.getElementById('taskCounter');
            const clearCompletedBtn = document.getElementById('clearCompletedBtn');

            // ---------- 渲染函数 ----------
            function render() {
                // 清空列表
                todoListEl.innerHTML = '';

                if (todos.length === 0) {
                    // 空状态展示
                    const emptyLi = document.createElement('li');
                    emptyLi.className = 'empty-message';
                    emptyLi.textContent = '✨ 还没有任务，添加一条吧';
                    todoListEl.appendChild(emptyLi);
                } else {
                    // 遍历生成任务项
                    todos.forEach(todo => {
                        const li = document.createElement('li');
                        li.className = `todo-item ${todo.completed ? 'completed' : ''}`;
                        li.dataset.id = todo.id;

                        // 复选框
                        const checkbox = document.createElement('input');
                        checkbox.type = 'checkbox';
                        checkbox.className = 'todo-check';
                        checkbox.checked = todo.completed;
                        checkbox.setAttribute('aria-label', `标记任务 "${todo.text}" 为${todo.completed ? '未完成' : '已完成'}`);
                        // 使用 change 事件监听勾选
                        checkbox.addEventListener('change', (e) => {
                            e.stopPropagation();
                            toggleTodo(todo.id);
                        });

                        // 任务文本
                        const textSpan = document.createElement('span');
                        textSpan.className = 'todo-text';
                        textSpan.textContent = todo.text;
                        // 点击文本也可以切换完成状态（方便操作）
                        textSpan.addEventListener('click', () => {
                            toggleTodo(todo.id);
                        });

                        // 删除按钮
                        const deleteBtn = document.createElement('button');
                        deleteBtn.className = 'delete-btn';
                        deleteBtn.innerHTML = '✕'; // 乘号表示删除
                        deleteBtn.setAttribute('aria-label', `删除任务 "${todo.text}"`);
                        deleteBtn.addEventListener('click', (e) => {
                            e.stopPropagation();
                            deleteTodo(todo.id);
                        });

                        li.appendChild(checkbox);
                        li.appendChild(textSpan);
                        li.appendChild(deleteBtn);
                        todoListEl.appendChild(li);
                    });
                }

                // 更新底部计数
                const total = todos.length;
                const completedCount = todos.filter(t => t.completed).length;
                taskCounter.textContent = `${total} 个任务 · ${completedCount} 已完成`;

                // 保存到 localStorage (每次渲染后保存，确保状态同步)
                saveTodos(todos);
            }

            // ---------- 操作函数 ----------
            // 切换完成状态
            function toggleTodo(id) {
                const todo = todos.find(t => t.id === id);
                if (todo) {
                    todo.completed = !todo.completed;
                    render(); // 重新渲染并保存
                }
            }

            // 删除单个任务
            function deleteTodo(id) {
                todos = todos.filter(t => t.id !== id);
                render();
            }

            // 添加新任务
            function addTodo() {
                const text = todoInput.value.trim();
                if (text === '') {
                    // 简单提示，不干扰
                    todoInput.placeholder = '请输入任务内容...';
                    todoInput.focus();
                    return;
                }

                // 生成唯一 id (时间戳 + 随机)
                const id = Date.now() + '-' + Math.random().toString(36).substring(2, 10);
                const newTodo = {
                    id: id,
                    text: text.slice(0, 200), // 限制长度
                    completed: false
                };

                todos.push(newTodo);
                todoInput.value = ''; // 清空输入框
                todoInput.placeholder = '写一个任务...'; // 恢复占位符
                todoInput.focus();
                render();
            }

            // 清除所有已完成任务
            function clearCompleted() {
                const hasCompleted = todos.some(t => t.completed);
                if (!hasCompleted) return; // 没有已完成任务，无操作

                todos = todos.filter(t => !t.completed);
                render();
            }

            // ---------- 事件绑定 ----------
            addBtn.addEventListener('click', addTodo);

            // 回车添加
            todoInput.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    addTodo();
                }
            });

            // 清除已完成按钮
            clearCompletedBtn.addEventListener('click', clearCompleted);

            // 当页面关闭或刷新前，已经通过 render 保存，但为了保险，再监听 beforeunload
            window.addEventListener('beforeunload', () => {
                saveTodos(todos);
            });

            // 初始化渲染
            render();

            // 可选：如果输入框为空时点击添加，轻微提示
            // 已经通过 placeholder 变化提示，不再额外弹窗
        })();
    </script>
</body>
</html>
```
### 功能与操作说明

