      还没有任务，添加一条吧
    </div>

    <!-- 底部统计 -->
    <div class="stats">
      <div>总计 <span id="totalCount">0</span> 项</div>
      <div>已完成 <span id="completedCount">0</span> 项</div>
    </div>
  </div>

  <script>
    (function() {
      'use strict';

      // ---------- 常量与状态 ----------
      const STORAGE_KEY = 'todo_list_data_v1';   // localStorage 键名

      // 任务数据结构: { id: string, text: string, completed: boolean }
      let tasks = [];

      // DOM 元素
      const addForm = document.getElementById('addForm');
      const taskInput = document.getElementById('taskInput');
      const taskList = document.getElementById('taskList');
      const emptyMessage = document.getElementById('emptyMessage');
      const totalCountSpan = document.getElementById('totalCount');
      const completedCountSpan = document.getElementById('completedCount');

      // ---------- 工具函数 ----------
      // 生成唯一 ID（不依赖外部库）
      function generateId() {
        return Date.now().toString(36) + '-' + Math.random().toString(36).substring(2, 10);
      }

      // 从 localStorage 读取任务
      function loadTasksFromStorage() {
        try {
          const stored = localStorage.getItem(STORAGE_KEY);
          if (!stored) return [];
          const parsed = JSON.parse(stored);
          // 简单校验数据格式，确保是数组且每项包含必要字段
          if (!Array.isArray(parsed)) return [];
          return parsed.filter(item => 
            item && 
            typeof item.id === 'string' && 
            typeof item.text === 'string' && 
            typeof item.completed === 'boolean'
          );
        } catch (error) {
          console.warn('读取本地存储失败，将使用空列表。', error);
          return [];
        }
      }

      // 保存任务到 localStorage
      function saveTasksToStorage() {
        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
        } catch (error) {
          console.warn('保存到本地存储失败（可能是存储空间已满或隐私模式）。', error);
        }
      }

      // ---------- 渲染 ----------
      // 根据 tasks 数组重新渲染整个列表
      function render() {
        // 清空列表
        taskList.innerHTML = '';

        // 更新空状态提示
        if (tasks.length === 0) {
          emptyMessage.style.display = 'flex';
        } else {
          emptyMessage.style.display = 'none';
        }

        // 遍历任务生成 DOM
        tasks.forEach(task => {
          const li = document.createElement('li');
          li.className = 'task-item' + (task.completed ? ' completed' : '');
          li.dataset.id = task.id;

          // 复选框区域
          const checkboxWrapper = document.createElement('div');
          checkboxWrapper.className = 'task-checkbox';

          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.checked = task.completed;
          checkbox.setAttribute('aria-label', `标记任务“${task.text}”为${task.completed ? '未完成' : '已完成'}`);
          // 使用 change 事件处理勾选
          checkbox.addEventListener('change', (e) => {
            e.stopPropagation();
            toggleTask(task.id);
          });

          const checkmarkSpan = document.createElement('span');
          checkmarkSpan.className = 'checkmark';

          checkboxWrapper.appendChild(checkbox);
          checkboxWrapper.appendChild(checkmarkSpan);

          // 任务文字
          const textSpan = document.createElement('span');
          textSpan.className = 'task-text';
          textSpan.textContent = task.text;
          // 点击文字也可以切换完成状态（方便操作）
          textSpan.addEventListener('click', () => {
            toggleTask(task.id);
          });

          // 删除按钮
          const deleteBtn = document.createElement('button');
          deleteBtn.className = 'delete-btn';
          deleteBtn.setAttribute('aria-label', `删除任务“${task.text}”`);
          deleteBtn.innerHTML = '&times;';  // 乘号作为删除图标，不依赖外部图标库
          deleteBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            deleteTask(task.id);
          });

          // 组装
          li.appendChild(checkboxWrapper);
          li.appendChild(textSpan);
          li.appendChild(deleteBtn);

          taskList.appendChild(li);
        });

        // 更新统计
        updateStats();
      }

      // 更新底部统计数字
      function updateStats() {
        const total = tasks.length;
        const completed = tasks.filter(t => t.completed).length;
        totalCountSpan.textContent = total;
        completedCountSpan.textContent = completed;
      }

      // ---------- 操作函数 ----------
      // 新增任务
      function addTask(text) {
        const trimmed = text.trim();
        if (trimmed === '') return;  // 空内容不添加

        const newTask = {
          id: generateId(),
          text: trimmed,
          completed: false
        };

        tasks.push(newTask);
        saveTasksToStorage();
        render();

        // 清空输入框并保持焦点
        taskInput.value = '';
        taskInput.focus();
      }

      // 切换任务完成状态
      function toggleTask(id) {
        const task = tasks.find(t => t.id === id);
        if (!task) return;

        task.completed = !task.completed;
        saveTasksToStorage();
        render();
      }

      // 删除任务
      function deleteTask(id) {
        tasks = tasks.filter(t => t.id !== id);
        saveTasksToStorage();
        render();
      }

      // ---------- 初始化与事件绑定 ----------
      function init() {
        // 从本地存储加载数据
        tasks = loadTasksFromStorage();

        // 首次渲染
        render();

        // 表单提交事件（添加任务）
        addForm.addEventListener('submit', (e) => {
          e.preventDefault();  // 阻止页面刷新
          addTask(taskInput.value);
        });

        // 输入框自动聚焦（提升体验）
        taskInput.focus();
      }

      // 页面加载完成后初始化
      document.addEventListener('DOMContentLoaded', init);
    })();
  </script>
</body>
</html>
