<body>
  <div class="todo-card">
    <h1>
      📋 待办清单
      <span>本地存储</span>
    </h1>
    <div class="subhead">
      任务自动保存在浏览器中 · 下次打开依然可见
    </div>

    <!-- 新增任务区域 -->
    <div class="add-section">
      <input type="text" id="taskInput" placeholder="写一个任务，比如 “买牛奶”" autocomplete="off" aria-label="新任务内容">
      <button id="addBtn" aria-label="添加任务">+ 添加</button>
    </div>

    <!-- 任务列表容器 -->
    <ul class="todo-list" id="todoList">
      <!-- 动态渲染任务 -->
    </ul>

    <!-- 底部统计 -->
    <div class="stats">
      <span id="taskCounter">0 个任务</span>
      <span id="completedCounter">0 已完成</span>
    </div>
  </div>

  <script>
    (function() {
      // ---------- 数据层 ----------
      const STORAGE_KEY = 'todo_list_data_v1';

      // 从 localStorage 读取任务数组，若不存在或损坏则返回空数组
      function loadTasks() {
        try {
          const stored = localStorage.getItem(STORAGE_KEY);
          if (!stored) return [];
          const parsed = JSON.parse(stored);
          // 确保是数组，且每个任务有 id, text, completed 字段
          if (!Array.isArray(parsed)) return [];
          return parsed.filter(task => 
            task && typeof task === 'object' && 
            typeof task.id === 'string' && 
            typeof task.text === 'string' && 
            typeof task.completed === 'boolean'
          );
        } catch (e) {
          console.warn('读取本地存储失败，使用空列表', e);
          return [];
        }
      }

      // 保存任务数组到 localStorage
      function saveTasks(tasks) {
        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
        } catch (e) {
          console.warn('保存到本地存储失败', e);
        }
      }

      // ---------- 状态 ----------
      let tasks = loadTasks();   // 当前任务数组

      // ---------- DOM 元素 ----------
      const todoListEl = document.getElementById('todoList');
      const taskInput = document.getElementById('taskInput');
      const addBtn = document.getElementById('addBtn');
      const taskCounter = document.getElementById('taskCounter');
      const completedCounter = document.getElementById('completedCounter');

      // ---------- 渲染函数 ----------
      function render() {
        // 清空列表
        todoListEl.innerHTML = '';

        // 如果没有任务，显示空状态
        if (tasks.length === 0) {
          const emptyLi = document.createElement('li');
          emptyLi.className = 'empty-message';
          emptyLi.textContent = '✨ 还没有任务，添加一条吧';
          todoListEl.appendChild(emptyLi);
        } else {
          // 遍历所有任务，创建列表项
          tasks.forEach(task => {
            const li = document.createElement('li');
            li.className = `todo-item ${task.completed ? 'completed' : ''}`;
            li.dataset.id = task.id;   // 用于事件委托

            // 复选框
            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.className = 'todo-check';
            checkbox.checked = task.completed;
            checkbox.setAttribute('aria-label', `标记任务“${task.text}”为${task.completed ? '未完成' : '已完成'}`);

            // 任务文本
            const textSpan = document.createElement('span');
            textSpan.className = 'todo-text';
            textSpan.textContent = task.text;

            // 删除按钮
            const deleteBtn = document.createElement('button');
            deleteBtn.className = 'delete-btn';
            deleteBtn.innerHTML = '✕';
            deleteBtn.setAttribute('aria-label', `删除任务“${task.text}”`);

            // 组装
            li.appendChild(checkbox);
            li.appendChild(textSpan);
            li.appendChild(deleteBtn);
            todoListEl.appendChild(li);
          });
        }

        // 更新统计
        const total = tasks.length;
        const completed = tasks.filter(t => t.completed).length;
        taskCounter.textContent = `${total} 个任务`;
        completedCounter.textContent = `${completed} 已完成`;
      }

      // ---------- 更新数据并重新渲染 + 保存 ----------
      function updateAndSave(newTasks) {
        tasks = newTasks;
        saveTasks(tasks);
        render();
      }

      // ---------- 添加任务 ----------
      function addTask() {
        const text = taskInput.value.trim();
        if (text === '') {
          // 简单提示：输入框抖动或聚焦（不干扰用户）
          taskInput.focus();
          taskInput.style.boxShadow = '0 0 0 3px rgba(199, 69, 58, 0.3)';
          setTimeout(() => {
            taskInput.style.boxShadow = '';
          }, 300);
          return;
        }

        // 生成唯一 id (时间戳 + 随机数)
        const id = Date.now() + '-' + Math.random().toString(36).substring(2, 10);
        const newTask = {
          id: id,
          text: text,
          completed: false
        };

        // 添加到数组并保存
        const newTasks = [...tasks, newTask];
        updateAndSave(newTasks);

        // 清空输入框并保持焦点
        taskInput.value = '';
        taskInput.focus();
      }

      // ---------- 切换完成状态 ----------
      function toggleComplete(taskId) {
        const newTasks = tasks.map(task => {
          if (task.id === taskId) {
            return { ...task, completed: !task.completed };
          }
          return task;
        });
        updateAndSave(newTasks);
      }

      // ---------- 删除任务 ----------
      function deleteTask(taskId) {
        const newTasks = tasks.filter(task => task.id !== taskId);
        updateAndSave(newTasks);
      }

      // ---------- 事件委托：处理列表内的点击（复选框和删除按钮） ----------
      todoListEl.addEventListener('click', (e) => {
        const target = e.target;

        // 处理复选框点击
        if (target.classList.contains('todo-check')) {
          const listItem = target.closest('.todo-item');
          if (listItem && listItem.dataset.id) {
            toggleComplete(listItem.dataset.id);
          }
          return;
        }

        // 处理删除按钮点击
        if (target.classList.contains('delete-btn')) {
          const listItem = target.closest('.todo-item');
          if (listItem && listItem.dataset.id) {
            deleteTask(listItem.dataset.id);
          }
          return;
        }
      });

      // ---------- 添加按钮点击 ----------
      addBtn.addEventListener('click', addTask);

      // ---------- 输入框回车添加 ----------
      taskInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          e.preventDefault();  // 防止意外提交或换行
          addTask();
        }
      });

      // ---------- 初始化渲染 ----------
      render();

      // 可选：当页面从 bfcache 恢复时重新读取存储（保证多标签页同步）
      window.addEventListener('pageshow', (event) => {
        if (event.persisted) {
          // 从缓存恢复，重新加载数据
          tasks = loadTasks();
          render();
        }
      });

      // 监听 storage 事件，实现多标签页同步（同一浏览器不同窗口）
      window.addEventListener('storage', (e) => {
        if (e.key === STORAGE_KEY) {
          // 其他标签页修改了数据，重新加载
          tasks = loadTasks();
          render();
        }
      });

    })();
  </script>
</body>
</html>
```
### 核心功能与操作说明

您可以通过以下方式轻松管理任务，所有数据都会自动保存在您的浏览器中。

-   **新增任务**：在输入框中输入任务内容，点击“添加”按钮或按回车键即可将任务加入列表。
-   **标记完成**：点击任务左侧的圆形复选框，可以切换任务的完成状态。已完成的任务会显示为带删除线的灰色样式。
-   **删除任务**：点击任务右侧的“✕”按钮，可以立即将该任务从列表中移除。
-   **数据持久化**：所有任务都会通过 `localStorage` 保存在您的浏览器中。关闭页面或浏览器后，再次打开该文件，之前的任务列表依然会完整显示。

