  <script>
    (function() {
      'use strict';

      // ---------- 常量与状态 ----------
      const STORAGE_KEY = 'todo_list_data_v1';   // 本地存储键名

      // 数据模型：数组，每个元素 { id: string, text: string, completed: boolean }
      let todos = [];

      // DOM 元素
      const todoInput = document.getElementById('todoInput');
      const addBtn = document.getElementById('addBtn');
      const todoList = document.getElementById('todoList');
      const emptyMessage = document.getElementById('emptyMessage');
      const taskCounter = document.getElementById('taskCounter');

      // ---------- 工具函数 ----------
      // 生成唯一ID (简单但足够可靠)
      function generateId() {
        return Date.now().toString(36) + '-' + Math.random().toString(36).substring(2, 10);
      }

      // 从 localStorage 读取数据
      function loadTodosFromStorage() {
        try {
          const stored = localStorage.getItem(STORAGE_KEY);
          if (stored) {
            const parsed = JSON.parse(stored);
            // 确保是数组，并且每个元素都有基本结构
            if (Array.isArray(parsed)) {
              // 过滤掉无效项，并确保字段完整
              todos = parsed.filter(item => item && typeof item === 'object' && typeof item.text === 'string')
                .map(item => ({
                  id: item.id || generateId(),
                  text: item.text,
                  completed: Boolean(item.completed)
                }));
            } else {
              todos = [];
            }
          } else {
            todos = [];
          }
        } catch (e) {
          console.warn('读取本地存储失败，使用空列表', e);
          todos = [];
        }
      }

      // 保存到 localStorage
      function saveTodosToStorage() {
        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
        } catch (e) {
          console.warn('保存到本地存储失败（可能是存储空间已满）', e);
        }
      }

      // ---------- 渲染界面 ----------
      function render() {
        // 清空列表
        todoList.innerHTML = '';

        // 根据 todos 渲染每一项
        if (todos.length === 0) {
          // 显示空状态提示，隐藏列表（列表本身为空，但为了布局保留）
          emptyMessage.style.display = 'block';
        } else {
          emptyMessage.style.display = 'none';

          todos.forEach(todo => {
            // 创建 li 元素
            const li = document.createElement('li');
            li.className = 'todo-item' + (todo.completed ? ' completed' : '');
            li.dataset.id = todo.id;   // 方便事件委托时获取ID

            // 复选框
            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.className = 'todo-checkbox';
            checkbox.checked = todo.completed;
            checkbox.setAttribute('aria-label', `标记任务 "${todo.text}" 为${todo.completed ? '未完成' : '已完成'}`);
            // 使用事件委托，但为了清晰也可以直接绑定，这里用委托统一处理
            // 但为了可访问性，保留原生checkbox，事件在父级监听

            // 任务文本
            const span = document.createElement('span');
            span.className = 'todo-text';
            span.textContent = todo.text;

            // 删除按钮
            const deleteBtn = document.createElement('button');
            deleteBtn.type = 'button';
            deleteBtn.className = 'delete-btn';
            deleteBtn.setAttribute('aria-label', `删除任务 "${todo.text}"`);
            deleteBtn.innerHTML = '✕';   // 乘号表示删除

            // 组装
            li.appendChild(checkbox);
            li.appendChild(span);
            li.appendChild(deleteBtn);
            todoList.appendChild(li);
          });
        }

        // 更新任务计数
        const total = todos.length;
        const completedCount = todos.filter(t => t.completed).length;
        taskCounter.textContent = `${total} 项任务 · ${completedCount} 已完成`;
      }

      // ---------- 核心操作 ----------
      // 添加新任务
      function addTodo() {
        const text = todoInput.value.trim();
        if (text === '') {
          // 简单提示：输入框抖动或聚焦，这里聚焦并轻微提示
          todoInput.focus();
          return;
        }

        const newTodo = {
          id: generateId(),
          text: text,
          completed: false
        };

        todos.push(newTodo);
        saveTodosToStorage();
        render();

        // 清空输入框并保持焦点
        todoInput.value = '';
        todoInput.focus();
      }

      // 切换完成状态
      function toggleTodo(id) {
        const todo = todos.find(t => t.id === id);
        if (todo) {
          todo.completed = !todo.completed;
          saveTodosToStorage();
          render();
        }
      }

      // 删除任务
      function deleteTodo(id) {
        todos = todos.filter(t => t.id !== id);
        saveTodosToStorage();
        render();
      }

